const EventEmitter = require('events');

// 1. Extend the EventEmitter class
class CoffeeMachine extends EventEmitter {
  constructor() {
    super(); // MUST call super() to initialize the Emitter!
    this.waterLevel = 100;
  }

  makeCoffee() {
    if (this.waterLevel < 20) {
      // 2. Emit events internally using 'this'
      this.emit('error', 'Not enough water!');
      return;
    }

    this.waterLevel -= 20;
    console.log("Brewing coffee...");

    // Simulate a 1 second brew time
    setTimeout(() => {
      this.emit('ready', 'Latte');
    }, 1000);
  }
}

// 3. Usage
const myMachine = new CoffeeMachine();

myMachine.on('ready', (type) => console.log(`DING! Your ${type} is ready!`));
myMachine.on('error', (err) => console.error(`BEEP BEEP! ${err}`));

myMachine.makeCoffee();
